const ASTRO_DEV_APP_ID = "astro:app";
function vitePluginApp() {
  return {
    name: "astro:app",
    resolveId: {
      filter: {
        id: new RegExp(`^${ASTRO_DEV_APP_ID}$`)
      },
      handler() {
        const url = new URL("./createAstroServerApp.js", import.meta.url);
        return this.resolve(url.toString());
      }
    }
  };
}
export {
  ASTRO_DEV_APP_ID,
  vitePluginApp
};
